import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "predictions")
os.makedirs(OUT, exist_ok=True)
T = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
def w(cid, text, basis, conf):
    d = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": dict(T)}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=1)

